// Generated by toolbox — the animation timeline.
// Do not edit by hand: change the Skia layer and export again.

import { evaluateTrack, ticksAt, type TimelineTrack } from "./toolbox-timeline";

export const NAME = "Split stages";

export const TIMELINE = {
  fps: 60,
  ticksPerFrame: 1000,
  durationTicks: 300000,
  durationSec: 5,
} as const;

// Toolbox canvas px — the scene's own coordinate space.
export const CANVAS = { width: 512, height: 512 } as const;

// Fractional toolbox frame at `seconds` (frame-aligned times are exact).
export function frameAt(seconds: number): number {
  "worklet";
  return ticksAt(seconds, TIMELINE.fps, TIMELINE.ticksPerFrame) / TIMELINE.ticksPerFrame;
}

// root.layer.imageFilters.0.program.uniforms.ns_5fcombo_5fedge_strength: keyframes s_combo_edge.strength (2 keys)
const T_b3: TimelineTrack = {"kind":"scalar","keys":[{"tick":0,"value":1.5,"easing":"easeInOutQuad"},{"tick":299000,"value":4,"easing":"linear"}]};

// root.layer.imageFilters.0.program.uniforms.ns_5fcombo_opacity0: keyframes s_combo.layer_opacity:L (2 keys)
const T_b25: TimelineTrack = {"kind":"scalar","keys":[{"tick":0,"value":0.35,"easing":"easeInOutSine"},{"tick":299000,"value":1,"easing":"linear"}]};

// root.children.0.layer.imageFilters.0.program.uniforms.ns_5fcombo_5fkuw_hardness: keyframes s_combo_kuw.hardness (2 keys)
const T_b71: TimelineTrack = {"kind":"scalar","keys":[{"tick":0,"value":4,"easing":"easeInOutSine"},{"tick":299000,"value":16,"easing":"linear"}]};

// root.children.0.children.0.paint.shader.program.uniforms.ns_5fn_offset_x: keyframes s_n.offset_x (2 keys)
const T_b81: TimelineTrack = {"kind":"scalar","keys":[{"tick":0,"value":0,"easing":"linear"},{"tick":299000,"value":0.9,"easing":"linear"}]};

// Every animated bind at `seconds` on the toolbox timeline, keyed by bind id
// (manifest.json maps ids to IR paths). Animated path geometry is not here:
// the component reads the pre-parsed PATH_* series itself.
export function sampleBinds(seconds: number) {
  "worklet";
  const tick = ticksAt(seconds, TIMELINE.fps, TIMELINE.ticksPerFrame);
  return {
    b1: seconds, // master clock (seconds)
    b3: evaluateTrack(T_b3, tick) as number, // keyframes s_combo_edge.strength (2 keys)
    b25: evaluateTrack(T_b25, tick) as number, // keyframes s_combo.layer_opacity:L (2 keys)
    b71: evaluateTrack(T_b71, tick) as number, // keyframes s_combo_kuw.hardness (2 keys)
    b81: evaluateTrack(T_b81, tick) as number, // keyframes s_n.offset_x (2 keys)
  };
}
